local xor = bit32 and bit32.bxor or function(a, b)
local r, p = 0, 1
while a > 0 or b > 0 do
local x, y = a % 2, b % 2
if x ~= y then r = r + p end
a, b, p = (a - x) / 2, (b - y) / 2, p * 2
end
return r
end
local out, n, kl = {}, 0, #K
H:gsub("%x%x", function(x)
n = n + 1
out[n] = string.char(xor(tonumber(x, 16), K[(n - 1) % kl + 1]))
end)
local f, e = (loadstring or load)(table.concat(out))
if not f then
warn("load error: " .. tostring(e))
return
end
return f()
